            <p style="font-size: 0.9em; color: #555;">Link: <a href="https://axiompaperless.com/">https://axiompaperless.com/</a></p>
        </div>
        `;

        const mailOptions = {
            from: 'paperless@apgmexico.mx',
            to: 'isabel.sierra@apgmexico.mx', // para mas correos usar comas para separarlos
            subject: `⚠️ APG Deviations Alert - ${new Date().toLocaleDateString()}`,
            html: htmlContent,
        };

        transporter.sendMail(mailOptions, (error, info) => {
            if (error) {
                console.log('Error sending deviations alert: ', error);
            } else {
                console.log('Alert email sent successfully');
            }
        });

    } catch (error) {
        console.error("Error en la función autoSendDeviationAlerts:", error);
    }
};

const sendApgGreenAlert = async () => {
    try {
        const mailOptions = {
            from: 'paperless@apgmexico.mx',
            to: 'APGEmployees@apgmexico.mx', // Lista de distribución
            ...templateApgGreen() // <-- Esto inyecta el subject, text y html
        };
        await transporter.sendMail(mailOptions);
        console.log("✅ Correo APG Green enviado correctamente");
    } catch (error) {
        console.error("❌ Error al enviar APG Green:", error);
    }
};

const sendPausaActivaAlert = async () => {
    try {
        const mailOptions = {
            from: 'paperless@apgmexico.mx',
            to: 'APGEmployees@apgmexico.mx',
            ...templatePausaActiva()
        };
        await transporter.sendMail(mailOptions);
        console.log("✅ Correo Pausa Activa enviado correctamente");
    } catch (error) {
        console.error("❌ Error al enviar Pausa Activa:", error);
    }
};

module.exports = {
    autoSendDeviationAlerts,
    sendApgGreenAlert,
    sendPausaActivaAlert,
};

