const User = require("../models/User.js");
const jwt = require("jsonwebtoken");
const Role = require("../models/Role.js");
const Dashboard = require("../models/Dashboard.js");
const Employees = require("../models/Employees.js");
const Company = require("../models/Company.js");
const Signature = require("../models/Signatures.js");
const PushToken = require("../models/PushToken.js");
console.log("ENV:", process.env.FIREBASE_CREDENTIALS_JSON ? "✅ cargada" : "❌ no encontrada");

// Getting all Users/////////////////////////////////////////////////////////////////////////////////////////////////////////////
const getUsers = async (req, res) => {
  const {
    CompanyId
  } = req.params;
  const {
    simple
  } = req.query;
  if (CompanyId.length !== 24) {
    return;
  }
  const company = await Company.find({
    _id: {
      $in: CompanyId
    }
  });
  if (!company) {
    return;
  }
  let users;
  if (simple === 'true') {
    users = await User.find({
      company: {
        $in: CompanyId
      }
    }).select('username email employee roles rolesAxiom signature').populate({
      path: 'employee',
      match: {
        active: true
      },
      // <-- 1. Agregamos el match aquí
      select: 'name lastName numberEmployee department position active',
      populate: [{
        path: "department",
        select: 'name'
      }, {
        path: "position",
        select: 'name'
      }]
    }).populate({
      path: "roles",
      select: 'name'
    }).populate({
      path: "rolesAxiom",
      select: 'name'
    }).populate({
      path: 'signature',
      select: 'signature'
    });
  } else {
    users = await User.find({
      company: {
        $in: CompanyId
      }
    }).populate({
      path: 'employee',
      match: {
        active: true
      },
      // <-- 1. Y también lo agregamos aquí
      populate: [{
        path: "department",
        select: 'name'
      }, {
        path: "position",
        select: 'name'
      }]
    }).populate({
      path: "roles",
      select: 'name'
    }).populate({
      path: "rolesAxiom",
      select: 'name'
    }).populate({
      path: "companyAccess"
    }).populate({
      path: 'signature',
      select: 'signature'
    });
  }
  users = users.filter(user => user.employee && user.employee.length > 0);
  res.json({
    status: "200",
    message: "Users Loaded",
    body: users
  });
};

//Crear un nuevo usuario///////////////////////////////////////////////////////////////////////////////////////////////////////////
const signUp = async (req, res) => {
  const {
    CompanyId
  } = req.params;
  const foundCompany = await Company.findById(CompanyId);
  if (!foundCompany) return res.status(404).json({
    status: "error",
    message: "Company not found"
  });
  try {
    const {
      username,
      email,
      password,
      signature,
      roles,
      rolesAxiom,
      employee,
      companyAccess,
      language
    } = req.body;

    //guardar firma
    const newSignature = new Signature({
      username,
      signature
    });
    const savedSignature = await newSignature.save();
    const newUser = new User({
      username,
      email,
      password: await User.encryptPassword(password),
      language,
      company: CompanyId
    });
    if (savedSignature) {
      const foundSignature = await Signature.find({
        username: {
          $in: username
        }
      });
      newUser.signature = foundSignature.map(signature => signature._id);
    }

    //Buscar roles en db y asignar a roles apg
    if (roles) {
      const foundRoles = await Role.find({
        name: {
          $in: roles
        }
      });
      newUser.roles = foundRoles.map(role => role._id);
    }
    //Buscar roles en db y asignar a roles axiom
    if (rolesAxiom) {
      const foundRoles = await Role.find({
        name: {
          $in: rolesAxiom
        }
      });
      newUser.rolesAxiom = foundRoles.map(role => role._id);
    }
    //buscar empleado y asisnar id de empleado a user
    if (employee) {
      const foundEmployees = await Employees.find({
        numberEmployee: {
          $in: employee
        }
      });
      newUser.employee = foundEmployees.map(employee => employee._id);
    }
    //compañia a la que puede tener acceso el usuario
    if (companyAccess) {
      const foundCompany = await Company.find({
        name: {
          $in: companyAccess
        }
      });
      newUser.companyAccess = foundCompany.map(company => company._id);
    }
    const savedUser = await newUser.save();
    const token = jwt.sign({
      id: savedUser._id
    }, process.env.SECRET, {
      expiresIn: 86400 // 24 Horas
      // expiresIn: 20,
    });
    res.json({
      status: "200",
      message: "User created"
    });
    // res.status(200).json({ token });
  } catch (error) {
    console.error("Error saving template:", error);
    return res.status(500).json({
      success: false,
      message: 'Server error while saving template',
      error: error.message
    });
  }
};
//Crear nuevo rol//////////////////////////////////////////////////////////////////////////////////////////////////////////
const newRole = async (req, res) => {
  const {
    name,
    description,
    category
  } = req.body;
