//Login de usuario existente//////////////////////////////////////////////////////////////////////////////////////////////
const signIn = async (req, res) => {
  const userFound = await User.findOne({
    username: req.body.username
  }).populate({
    path: "roles",
    select: "name"
  }).populate({
    path: "companyAccess"
  }).populate({
    path: "company"
  }).populate({
    path: "employee"
  });

  // 1. Validaciones iniciales
  if (!userFound) {
    return res.status(404).json({
      token: null,
      message: "User not found",
      status: "404"
    });
  }
  const matchPassword = await User.comparePassword(req.body.password, userFound.password);
  if (userFound.employee[0].active === false) {
    return res.status(404).json({
      token: null,
      message: "User disabled",
      status: "404"
    });
  }
  if (!matchPassword) {
    return res.status(404).json({
      token: null,
      message: "Invalid password",
      status: "404"
    });
  }

  // 2. Generación del Token
  const token = jwt.sign({
    id: userFound._id
  }, process.env.SECRET, userFound.username !== 'SupplierAPG' ? {
    expiresIn: 86400
  } : {});

  // 3. Extracción de IDs de compañía usando .find()
  const apgAccess = userFound.companyAccess.find(c => c.name === "APG Mexico");
