    QuarantineR: [44],
    QuarantineC: [45]
  };

  // 7. Configuración de Mapeo de Roles Axiom (Afecta tanto a AXG como a APG)
  const axgRoleMap = {
    admin: [0],
    moderador: [1],
    GeneralR: [2],
    SetupR: [3],
    QualityR: [4],
    ProductionR: [5],
    LogisticR: [6],
