    ValidationCheckQ: [42],
    ValidationCheckP: [43],
    // QUARANTINE ROLES
    QuarantineR: [44],
    QuarantineC: [45]
  };

  // 8. Aplicar accesos buscando asíncronamente los roles a la DB
  const [roles, rolesAxiom] = await Promise.all([Role.find({
    _id: {
      $in: userFound.roles
    }
  }), Role.find({
    _id: {
      $in: userFound.rolesAxiom
    }
  })]);
  roles.forEach(role => {
    const indices = apgRoleMap[role.name] || [];
    indices.forEach(idx => userAccessApg[idx] = "true");
  });
  rolesAxiom.forEach(role => {
    const indices = axgRoleMap[role.name] || [];
    indices.forEach(idx => userAccessAXG[idx] = "true");
  });

  // 9. Respuesta
  res.json({
    token,
    status: "200",
    message: "login complete",
    userData,
    userAccessApg,
    userAccessAXG
  });
};

