const updateUser = async (req, res) => {
  const {
    userId
  } = req.params;
  const user = await User.findById(userId);
  if (!user) return res.status(404).json({
    status: "error",
    message: "Error al buscar usuario"
  });
  try {
    const userUpd = [];
    const foundRoles = await Role.find({
      name: {
        $in: req.body.roles
      }
    });
    userUpd.roles = foundRoles.map(role => role._id);
    const foundRolesAxiom = await Role.find({
      name: {
        $in: req.body.rolesAxiom
      }
    });
    userUpd.rolesAxiom = foundRolesAxiom.map(role => role._id);
    const foundCompanyAccess = await Company.find({
      name: {
        $in: req.body.companyAccess
      }
    });
    userUpd.companyAccess = foundCompanyAccess.map(company => company._id);
    userUpd.username = req.body.username;
    userUpd.email = req.body.email;
    userUpd.language = req.body.language;
    if (user.password !== req.body.password) {
      userUpd.password = await User.encryptPassword(req.body.password);
    } else {
      userUpd.password = req.body.password;
    }
    const signature = req.body.signature;
    const updatedSignature = await Signature.updateOne({
      username: req.body.username
    }, {
      $set: {
        signature
      }
    });
    const {
      username,
      email,
      password,
      roles,
      rolesAxiom,
      companyAccess,
      language
    } = userUpd;
    const updatedUser = await User.updateOne({
      _id: userId
    }, {
      $set: {
        username,
        email,
        password,
        roles,
        rolesAxiom,
        companyAccess,
        language
      }
    });
    if (!updatedUser) {
      res.status(403).json({
        status: "403",
        message: "User not Updated"
      });
    }
    res.status(200).json({
      status: "200",
      message: "User Updated"
    });
  } catch (error) {
    console.error("Error saving template:", error);
    return res.status(500).json({
      success: false,
      message: 'Server error while saving template',
      error: error.message
    });
  }
};
