    token: null,
    message: "Invalid current password",
    status: "404"
  });
  userUpd.password = await User.encryptPassword(req.body.newpassword);
  const {
    password
  } = userUpd;
  const updatedPassword = await User.updateOne({
    _id: userId
  }, {
    $set: {
      password
    }
  });
  if (!updatedPassword) {
    res.status(403).json({
