// Controlador para el Kaizen
const Kaizen = require("../models/Kaizen.js");
const Company = require("../models/Company.js");
const Employees = require("../models/Employees.js");
const Deparment = require("../models/Deparment.js");
const Suggestion = require("../models/Suggestion.js");
const KaizenPoints = require("../models/KaizenPoints");
const User = require("../models/User.js");
const RewardsKaizen = require("../models/RewardsKaizen.js");
const KaizenPointsRedeem = require("../models/KaizenPointsRedeem.js");
const KaizenInvestigations = require("../models/KaizenInvestigations.js");

//Actualizacion de sdk de aws v3
const {
  S3Client,
  DeleteObjectCommand
} = require("@aws-sdk/client-s3");
const s3 = new S3Client({
  region: process.env.S3_BUCKET_REGION,
  credentials: {
    accessKeyId: process.env.S3_ACCESS_KEY,
    secretAccessKey: process.env.S3_SECRET_ACCESS_KEY
  }
});
const nodemailer = require("nodemailer");

// CREAR NUEVA SUGERENCIA ////////////////////////////////////////////////////////////////////////////////////////////////////////
const createSuggestion = async (req, res) => {
  const {
    CompanyId
  } = req.params;
  try {
    const {
      suggestionTitle,
      currentMethod,
      proposedMethod,
      benefits,
      partNumber,
      createdBy,
      area,
      createdDate,
      otherIdeators
    } = req.body;

    // Procesar la firma
    let signatureImgKey = "";
    if (req.files && req.files["signatureImage"] && req.files["signatureImage"].length > 0) {
      signatureImgKey = req.files["signatureImage"][0].key.split('/').pop();
    }

    // Crear objeto Suggestion
    const suggestion = new Suggestion({
      suggestionTitle,
      currentMethod,
      proposedMethod,
      benefits,
      area,
      partNumber,
      createdDate,
      otherIdeators,
      signatureImg: signatureImgKey
    });

    // Vincular Relaciones en el objeto Suggestion
    if (createdBy) {
      const foundEmployee = await Employees.find({
        _id: {
          $in: createdBy
        }
      });
      suggestion.createdBy = foundEmployee.map(e => e._id);
    }
    if (CompanyId) {
      const foundCompany = await Company.find({
        _id: {
          $in: CompanyId
        }
      });
      suggestion.company = foundCompany.map(c => c._id);
    }

    // Generar Consecutivo (APG-SUG-X)
    const lastSuggestion = await Suggestion.find({
      company: {
        $in: CompanyId
      }
    }).sort({
      consecutive: -1
    }).limit(1);
    if (lastSuggestion.length === 0) {
      suggestion.consecutive = 1;
      suggestion.idSuggestion = "APG-SUG-1";
    } else {
      const nextConsecutive = lastSuggestion[0].consecutive + 1;
      suggestion.consecutive = nextConsecutive;
      suggestion.idSuggestion = "APG-SUG-" + nextConsecutive;
    }

    //  Guardar la Sugerencia en BD
    await suggestion.save();

    // LOGICA KAIZEN POINTS
    if (createdBy) {
      await KaizenPoints.findOneAndUpdate({
        employee: createdBy
      }, {
        $inc: {
          totalPoints: 20
        },
        $push: {
          history: {
            activity: "Sugerencia generada",
            reference: suggestion.idSuggestion,
            points: 20,
            date: new Date()
          }
        },
        $setOnInsert: {
          company: CompanyId
        }
      }, {
        upsert: true,
        new: true
      });
    }
    res.status(200).json({
      status: "200",
      message: "Sugerencia guardada correctamente y puntos asignados",
      body: suggestion
    });
  } catch (error) {
    console.error("Error creating suggestion:", error);
    res.status(500).json({
      status: "error",
      message: "Error al guardar la sugerencia",
      error: error.message
    });
  }
};

// OBTENER SUGERENCIAS //////////////////////////////////////////////////////////////////////////////////////////////////////
const getSuggestions = async (req, res) => {
  const {
    CompanyId
  } = req.params;
  if (CompanyId.length !== 24) {
    return;
  }
  const company = await Company.find({
    _id: {
      $in: CompanyId
    }
  });
  if (!company) {
    return;
  }
  const suggestions = await Suggestion.find({
    company: {
      $in: CompanyId
    }
  }).sort({
    consecutive: -1
  }).populate({
    path: 'createdBy',
    select: "name lastName numberEmployee picture",
    populate: {
      path: "department position",
      select: "name"
    }
  }).populate({
    path: 'modifiedBy',
    select: "username employee",
    populate: {
      path: "employee",
      select: "name lastName numberEmployee",
      populate: {
        path: "department position",
        select: "name"
      }
    }
  }).populate({
    path: "investigationId",
    select: "-suggestionId",
    populate: {
      path: "q14_advisors",
      select: "username employee",
      populate: {
        path: "employee",
        select: "name lastName"
      }
    }
  });
  res.json({
    status: "200",
    message: "Suggestions Loaded",
    body: suggestions
  });
};

// OBTENER PUNTOS DE UN EMPLEADO //////////////////////////////////////////////////////////////////////////////////////////////////////
const getEmployeePoints = async (req, res) => {
  try {
    const {
      employeeId
    } = req.params;
    const pointsRecord = await KaizenPoints.findOne({
      employee: employeeId
    });
    if (!pointsRecord) {
      return res.status(404).json({
        status: "404",
        message: "No points found"
      });
    }
    res.status(200).json({
      status: "200",
      body: pointsRecord
    });
  } catch (error) {
    console.error(error);
    res.status(500).json({
      status: "error",
      message: error.message
    });
  }
};

// FUNCION PARA OBTENER TODOS LOS PUNTOS KAIZEN ////////////////////////////////////////////////////////////////////////////////////////////////////////
const getKaizenPoints = async (req, res) => {
  const {
    CompanyId
  } = req.params;
  if (CompanyId.length !== 24) {
    return;
  }
  const company = await Company.find({
    _id: {
      $in: CompanyId
    }
  });
  if (!company) {
    return;
  }
  const kaizenPoints = await KaizenPoints.find({
    company: {
      $in: CompanyId
    }
  }).sort({
    totalPoints: -1
  }).populate({
    path: 'employee',
    select: "name lastName numberEmployee picture",
    populate: {
      path: "department position",
      select: "name"
    }
  });
  res.json({
    status: "200",
    message: "Kaizen Points Loaded",
    body: kaizenPoints
  });
};

// FUNCION PARA CREAR UN NUEVO REGISTRO DE PUNTOS KAIZEN //////////////////////////////////////////////////////////////////////////////////////////////////////////
const createNewRegister = async (req, res) => {
  try {
    const user = await User.findById(req.userId);
    const {
      CompanyId
    } = req.params;
    const {
      activity,
      reference,
      points,
      employee
    } = req.body;
    const foundCompany = await Company.findById(CompanyId);
    const foundEmployee = await Employees.findById(employee);
    if (!foundCompany) {
      return res.status(404).json({
        status: "error",
        message: "Compañia no encontrada"
      });
    }
    if (!foundEmployee) {
      return res.status(404).json({
        status: "error",
        message: "Empleado no encontrado"
      });
    }
    await KaizenPoints.findOneAndUpdate({
      employee: employee
    }, {
      $inc: {
        totalPoints: points
      },
      $push: {
        history: {
          activity: activity,
          reference: reference,
          points: points,
          date: new Date(),
          registeredBy: user._id
        }
      },
      $setOnInsert: {
        company: CompanyId
      }
    }, {
      upsert: true,
      new: true
    });
    res.status(200).json({
      status: "200",
      message: 'Nuevo Registro Creado'
    });
  } catch (error) {
    res.status(500).json({
      status: "error",
      message: "Error al Crear registro",
      error: error.message
    });
  }
};

// FUNCION PARA MODIFICAR PUNTOS MANUALMENTE ///////////////////////////////////////////////////////////////////////////////////////////////////////////
const manualPointsUpdate = async (req, res) => {
  try {
    const user = await User.findById(req.userId);
    const {
      CompanyId
    } = req.params;
    const {
      RegisterId
    } = req.params;
    const {
      activity,
      reference,
      points,
      action
    } = req.body;
    if (!reference || !points || !action) {
      return res.status(400).json({
        status: "error",
        message: "Faltan datos requeridos (employeeId, points, action)"
      });
    }
    const absolutePoints = Math.abs(parseInt(points));
    const finalPoints = action === 'subtract' ? -absolutePoints : absolutePoints;
    const updatedRecord = await KaizenPoints.findOneAndUpdate({
      _id: RegisterId
    }, {
      $inc: {
        totalPoints: finalPoints
      },
      $push: {
        history: {
          activity: activity,
          reference: reference,
          points: finalPoints,
          date: new Date(),
          registeredBy: user._id
        }
      },
      $setOnInsert: {
        company: CompanyId
      }
    }, {
      new: true
    });
    res.status(200).json({
      status: "200",
      message: action === 'add' ? "Puntos agregados correctamente" : "Puntos descontados correctamente",
      body: updatedRecord
    });
  } catch (error) {
    console.error(error);
    res.status(500).json({
      status: "error",
      message: "Error al actualizar puntos manuales",
      error: error.message
    });
  }
};

