const mongoose = require("mongoose");
const {
  Schema
} = mongoose;
const SuggestionSchema = new Schema({
  consecutive: {
    type: Number
  },
  idSuggestion: {
    type: String
  },
  // Ej: APG-SUG-001

  // Campos del formato
  suggestionTitle: {
    type: String,
    required: true
  },
  // "Esta es mi sugerencia"
  currentMethod: {
    type: String
  },
  // Método Actual
  proposedMethod: {
    type: String
  },
