  benefits: {
    type: String
  },
  // Beneficios

  // Datos
  partNumber: {
    type: String
  },
  // Relaciones
  company: [{
    type: Schema.Types.ObjectId,
    ref: "Company"
  }],
  createdBy: [{
    type: Schema.Types.ObjectId,
    ref: "Employees"
  }],
  // Nombre
  modifiedBy: [{
    type: Schema.Types.ObjectId,
    ref: "User"
  }],
  // Nombre
  area: {
    type: String
  },
  // Ubicación
  value: {
    type: Number
  },
  rejectReason: {
    type: String
  },
  // Fechas y Firma
  createdDate: {
    type: Date,
    default: Date.now
  },
  signatureImg: {
    type: String
  },
  // Key de S3

  otherIdeators: {
    type: String
  },
  // Control interno
  status: {
    type: String,
    default: "New"
  },
  version: {
    type: Number,
    default: 1
  },
