const { Router } = require("express");
const router = Router();
const {
  checkDuplicateEmployeeNo
} = require("../middlewares/verifySignup.js");
const {
  verifyToken,
  isModerator,
  isAdmin,
  isAutorized
} = require("../middlewares/auth.Jwt.js");
const {
  getPositions,
  getDepartments,
  getEmployees,
  updateEmployeeUser,
  modifyProfileImg,
  updateEmployee,
  createEmployee
} = require("../controllers/employees.controller.js");
const uploadPicture = require("../middlewares/uploadProfileImg.js");

// RUTA PARA CREAR UN NUEVO EMPLEADO //
router.post(
  "/NewEmployee/:CompanyId",
  verifyToken,
  isAutorized,
  isModerator,
  uploadPicture,
  createEmployee
);












///Route to get All the positions///
router.get(
  "/Positions",
  getPositions
);
/// Route to get All the departments///
router.get(
  "/Departments",
  getDepartments
);
///Route to get employees///
router.post(
  "/Employees/:employeeStatus/:CompanyId",
  getEmployees
);
///Route to update user field in employee///
router.put(
  "/UpdateEmployee/User/:employeeId/:CompanyId",
  verifyToken,
  isAutorized,
  isAdmin,
  updateEmployeeUser
);
///Route to update employee///
router.put(
  "/UpdateEmployee/:employeeId/:CompanyId",
  verifyToken,
  isAutorized,
  isModerator,
  updateEmployee
);
///Route to update picture of employee///
router.put(
  "/UpdateEmployee/Picture/:employeeId/:CompanyId",
  verifyToken,
  isAutorized,
  isModerator,
  uploadPicture,
  modifyProfileImg
);

module.exports = router;

