const Customer = require("../models/Customer.js");
const Parts = require("../models/Parts.js");
const User = require("../models/User.js");
const Company = require("../models/Company.js");
const {
  sendEmailMiddlewareResponse
} = require("../middlewares/mailer.js");
const Deviation = require("../models/Deviation.js");
const Employees = require("../models/Employees.js");
const Role = require("../models/Role.js");
const DeviationRequest = require("../models/DeviationRequest.js");
const DeviationsNew = require("../models/DeviationsNew.js");

//Actualizacion de sdk de aws v3
const {
  S3Client,
  DeleteObjectCommand,
  DeleteObjectsCommand
} = require("@aws-sdk/client-s3");
const s3 = new S3Client({
  region: process.env.S3_BUCKET_REGION,
  credentials: {
    accessKeyId: process.env.S3_ACCESS_KEY,
    secretAccessKey: process.env.S3_SECRET_ACCESS_KEY
  }
});
const extractRows = (body, prefix) => {
  const normalize = val => !val ? [] : Array.isArray(val) ? val : [val];
  const risks = normalize(body[`${prefix}Risk`]);
  const measurements = normalize(body[`${prefix}Measurement`]);
  const responsibles = normalize(body[`${prefix}Responsible`]);
  const dueDates = normalize(body[`${prefix}DueDate`]);
  if (risks.length === 0) return [];
  return risks.map((risk, index) => {
    const respId = responsibles[index];
    return {
      risk: risk,
      measurement: measurements[index] || '',
      responsible: respId && respId.trim().length > 0 ? respId : null,
      dueDate: dueDates[index] || null
    };
  }).filter(row => row.risk && row.risk.trim() !== '');
};
const extractNewRows = (body, prefix) => {
  const normalize = val => !val ? [] : Array.isArray(val) ? val : [val];
  const risks = normalize(body[`${prefix}Risk`]);
  const measurements = normalize(body[`${prefix}Measurement`]);
  const responsibles = normalize(body[`${prefix}Responsible`]);
  const dueDates = normalize(body[`${prefix}DueDate`]);
  const closeDates = normalize(body[`${prefix}CloseDate`]); // 1. Normalizamos las fechas de cierre

  if (risks.length === 0) return [];
  return risks.map((risk, index) => {
    const respId = responsibles[index];
    const dueDate = dueDates[index];
    const closeDate = closeDates[index];
    return {
      risk: risk,
      measurement: measurements[index] || '',
      responsible: respId && respId.trim().length > 0 ? respId : null,
      dueDate: dueDate && dueDate.trim().length > 0 ? dueDate : null,
      closeDate: closeDate && closeDate.trim().length > 0 ? closeDate : null
    };
  }).filter(row => row.risk && row.risk.trim() !== ''); // Mantenemos tu filtro de seguridad
};

//create deviation request//////////////////////////////////////////////////////////////////////////////////////
const createDeviation = async (req, res) => {
  const {
    CompanyId
  } = req.params;
  try {
    // 1. Extraer TODOS los datos del body
    const {
      requestBy,
      severity,
      deviationType,
      deviationDate,
      implementationDate,
      customer,
      partNumber,
      applyTo,
      implementationTime,
      machine,
      supplier,
      sectionTwo,
      termDevRequest,
      quantity,
      timePeriodStart,
      timePeriodEnd,
      other,
      comments,
      reason,
      consequence,
      // Variables de decisión de firmas (frontend envia "Yes" o "No")
      qualitySignStatus,
      seniorSignStatus,
      customerSignStatus
    } = req.body;

    // 2. Procesar Imágenes (Multer)
    let deviationImages = [];
    if (req.files && req.files["deviationImages"]) {
      deviationImages = req.files["deviationImages"].map(file => ({
        img: file.key
      }));
    }

    // 3. Generar Consecutivo (APG-2026-XXX)
    const anioActual = new Date().getFullYear();
    const ultimaDesviacion = await Deviation.findOne({
      createdAt: {
        $gte: new Date(`${anioActual}-01-01T00:00:00.000Z`),
        $lt: new Date(`${anioActual + 1}-01-01T00:00:00.000Z`)
      }
    }).sort({
      consecutive: -1
    });
    const nextConsecutive = ultimaDesviacion ? ultimaDesviacion.consecutive + 1 : 1;
    const generatedNumber = `APG-${anioActual}-${String(nextConsecutive).padStart(3, "0")}`;

    // 4. CREAR EL OBJETO DEVIATION (Estructura Nueva)
    const newDeviation = new Deviation({
      // Metadatos
      deviationNumber: generatedNumber,
      consecutive: nextConsecutive,
      version: 2,
      deviationStatus: "Open",
      // Estado inicial de toda la desviación

      // Datos Generales
      severity,
      deviationType,
      deviationDate,
      implementationDate,
      applyTo,
      implementationTime,
      machine,
      supplier,
      sectionTwo,
      termDevRequest,
      quantity,
      timePeriodStart,
      timePeriodEnd,
      other,
      comments,
      reason,
      consequence,
      deviationImages,
      // Tablas de Riesgo (Usamos el helper extractRows)
      // Nota: Aunque vengan vacíos desde "Nueva Desviación", esto prepara la estructura.
      riskAssessment: {
        product: extractRows(req.body, 'product'),
        process: extractRows(req.body, 'process')
      },
      actions: {
        corrective: extractRows(req.body, 'corrective'),
        preventive: extractRows(req.body, 'preventive')
      },
      followUp: {
        corrective: extractRows(req.body, 'followCorrective'),
        preventive: extractRows(req.body, 'followPreventive')
      },
      // Firmas: Configuramos el estado inicial basado en la decisión del usuario
      signatures: {
        qualityValidation: {
          status: qualitySignStatus === 'Yes' ? 'Pending' : 'NA'
        },
        seniorManager: {
          status: seniorSignStatus === 'Yes' ? 'Pending' : 'NA'
        },
        customer: {
          status: customerSignStatus === 'Yes' ? 'Pending' : 'NA'
        },
        // Las firmas de los gerentes (Section 5) las dejamos pendientes por defecto
        // Si también son opcionales, necesitarías agregar selects en el front para ellas.
        riskAssessment: {
          qualityManager: {
            status: 'Pending'
          },
          productionManager: {
            status: 'Pending'
          },
          processManager: {
            status: 'Pending'
          },
          automationManager: {
            status: 'Pending'
          }
        }
      }
    });

    // 5. Validar y Asignar Referencias (User, Customer, Parts, Company)

    // Request By (Usuario)
    if (requestBy) {
      const reqByArray = Array.isArray(requestBy) ? requestBy : [requestBy];
      const foundUsers = await User.find({
        _id: {
          $in: reqByArray
        }
      });
      if (!foundUsers.length) return res.status(404).json({
        status: "error",
        message: "Usuario RequestBy no encontrado"
      });
      newDeviation.requestBy = foundUsers.map(u => u._id);
    }

    // Customer
    if (customer) {
      const custArray = Array.isArray(customer) ? customer : [customer];
      const foundCustomers = await Customer.find({
        _id: {
          $in: custArray
        }
      });
      if (!foundCustomers.length) return res.status(404).json({
        status: "error",
        message: "Customer no encontrado"
      });
      newDeviation.customer = foundCustomers.map(c => c._id);
    }

    // Part Number
    if (partNumber) {
      const partArray = Array.isArray(partNumber) ? partNumber : [partNumber];
      const foundParts = await Parts.find({
        _id: {
          $in: partArray
        }
      });
      if (!foundParts.length) return res.status(404).json({
        status: "error",
        message: "Parts no encontrado"
      });
      newDeviation.partNumber = foundParts.map(p => p._id);
    }

    // Company
    if (CompanyId) {
      const foundCompanies = await Company.find({
        _id: CompanyId
      });
      if (!foundCompanies.length) return res.status(404).json({
        status: "error",
        message: "Company no encontrado"
      });
      newDeviation.company = foundCompanies.map(c => c._id);
    }

    // 6. Guardar en Base de Datos
    const savedDeviationRequest = await newDeviation.save();
    if (!savedDeviationRequest) {
      return res.status(403).json({
        status: "403",
        message: "Deviation not Saved"
      });
    }

    // 7. Respuesta Exitosa
    res.json({
      status: "200",
      message: "New Deviation created successfully",
      savedDeviationRequest
    });
  } catch (error) {
    console.error("Error creating deviation:", error);
    res.status(500).json({
      status: "error",
      message: "Error al guardar desviacion",
      error: error.message
    });
  }
};

