    implementationDate,
    implementationTime,
    customerId,
    partId,
    supplier,
    machine,
    processOwner,
    deviationDescription,
    interimControlMeasure
  } = req.body;
  const termRequest = JSON.parse(req.body.termRequest);
  let deviationImages = [];
  if (req.files && req.files["deviationImages"]) {
    deviationImages = req.files["deviationImages"].map(file => ({
      img: file.key
    }));
  }
  try {
