const { Router } = require("express");
const router = Router();
const {
    createPart,
    udpateParts,
    getParts,
    getTrainingParts
} = require("../controllers/parts.controller.js");
const {
    verifyToken,
    isQualityRW,
    isAutorized
} = require("../middlewares/auth.Jwt.js");

///Route to create new part///
router.post(
    "/NewPart/:CompanyId",
    verifyToken,
    isAutorized,
    isQualityRW,
    createPart
);
///Route to update part number///
router.put("/UpdatePart/:partId/:CompanyId",
    verifyToken,
    isAutorized,
    isQualityRW,
    udpateParts
);
///Route to get all part by company///
router.get("/Parts/:CompanyId",
    verifyToken,
    isAutorized,
    getParts
);

// RUTA PARA OBTENER PARTES PARA TRAINING //
router.get("/TrainingParts/:CompanyId",
    verifyToken,
    isAutorized,
    getTrainingParts
);




module.exports = router;

