const updateDevolucionStatus = async (req, res) => {
  const {
    idDevolucion
  } = req.params;
  const {
    status,
    usuario,
    reason
  } = req.body; // status: 'confirmed', 'validated', 'rejected'

  // Configuración de hora
  const dateMX = new Date(new Date().toLocaleString("en-US", {
    timeZone: "America/Mexico_City"
  }));
  const hourMX = dateMX.getHours();
  const minutesMX = dateMX.getMinutes();
  const time = `${String(hourMX).padStart(2, '0')}:${String(minutesMX).padStart(2, '0')}`;
  try {
    const devolucion = await Devolucion.findOne({
      idDevolucion
    });
    if (!devolucion) return res.status(404).json({
      status: "error",
      message: "Devolución no encontrada"
    });

    // Buscar ID del usuario que ejecuta la acción
    const actionUser = await User.findOne({
      username: usuario
    });
    if (!actionUser) return res.status(404).json({
      status: "error",
      message: "Usuario no encontrado"
    });

    // Lógica de transición de estados
    switch (status) {
      case 'confirmed':
        // Solo se puede confirmar si está 'started' o 'rejected'
        if (devolucion.dStatus !== 'started' && devolucion.dStatus !== 'rejected') {
          return res.status(400).json({
            status: "error",
            message: "No se puede confirmar en el estado actual."
          });
        }
        devolucion.dStatus = 'confirmed';
        devolucion.confirmedBy = actionUser._id;
        // Si venía de rechazo, limpiamos el motivo anterior para indicar que se corrigió
        if (devolucion.dStatus === 'rejected') {
          // Opcional: Podrías mantener el historial, pero aquí limpiamos para "nueva confirmación"
          // devolucion.rejectionReason = null; 
        }
        break;
      case 'validated':
        if (devolucion.dStatus !== 'confirmed') {
          return res.status(400).json({
            status: "error",
            message: "Solo se pueden validar devoluciones confirmadas."
          });
        }
        devolucion.dStatus = 'validated';
        devolucion.validatedBy = actionUser._id;
        devolucion.actionTime = time;
        break;
      case 'rejected':
        if (devolucion.dStatus !== 'confirmed') {
          return res.status(400).json({
            status: "error",
            message: "Solo se pueden rechazar devoluciones confirmadas."
          });
        }
        if (!reason) {
          return res.status(400).json({
            status: "error",
            message: "Se requiere un motivo para rechazar."
          });
        }
        devolucion.dStatus = 'rejected';
        devolucion.rejectedBy = actionUser._id;
        devolucion.rejectionReason = reason;
        devolucion.actionTime = time;
        break;
      default:
        return res.status(400).json({
          status: "error",
          message: "Estatus inválido."
        });
    }
    await devolucion.save();
    res.status(200).json({
      status: "200",
      message: `Devolución actualizada a: ${status}`,
      body: devolucion
    });
  } catch (error) {
    console.error(error);
    res.status(500).json({
      status: "error",
      message: "Error actualizando estatus",
      error: error.message
    });
  }
};

