    verifyToken,
    isAutorized,
    isQuarantineC,
    createQUARequest
);

router.get("/GetRecords/:CompanyId",
    verifyToken,
    isAutorized,
    isQuarantineR,
    getAllRegisters
);

router.put("/updateRegisters/:CompanyId/:moveID",
    verifyToken,
    isAutorized,
    isQuarantineC,
    updateRegisters
);

router.put("/release/:CompanyId",
    verifyToken,
    isAutorized,
    isQuarantineC,
    releaseFromQuarantine
);

module.exports = router;

