const mongoose = require("mongoose");

const QuarantineSchema = new mongoose.Schema({
    moveID: {type: String, required: true },
    user: {
        ref: "User",
        type: mongoose.Schema.Types.ObjectId,
    },
    quarantineDate: {type: Date},
    itemID: {
        ref: "Items",
        type: mongoose.Schema.Types.ObjectId,
    },
    seriales: [{
        serial:{type: String}, 
        cantidad: {type: Number}
    }],
    batch: {type: String},
