                        const mailOptions = {
                            from: 'paperless@apgmexico.mx',
                            to: emailsG.join(', '), // Join the receivers array into a comma-separated string
                            subject: `${subjectG}\n`,
                           // text: 'DO NOT REPLY BACK this email - Autogenerated \n\n' +
                             //   `${message}`,
                            
                            //attachments: [{
                             //   filename: 'Alerta2.jpg',
